 "Compañeros": "Colegas",
 "<b style=\"font-size:25px;color:#5b6fc4\">Compañeros</b><br><span style=\"font-size:21px;color:#2d2616\">Por ser quienes hicieron esto posible.</span>": "<b style=\"font-size:25px;color:#5b6fc4\">Colegas</b><br><span style=\"font-size:21px;color:#2d2616\">Por serem quem tornou isto possível.</span>",
